SELECT DISTINCT e.event_name, e.call_point_id, cp.product, cp.funnel_name FROM event e JOIN call_point cp USING(call_point_id)
WHERE e.system_id = 'gtm_datalayer' AND e.gtm_tagged = 0 AND e.kind = 'track' AND e.naming_style = {{ q1.naming_style | q }}
ORDER BY e.event_name

SELECT p.name, p.value_expr, p.value_kind, p.presence FROM param p JOIN event e USING(event_id)
WHERE e.system_id = {{ q1.system_id | q }} AND e.event_name = {{ q1.event_name | q }} AND e.call_point_id = {{ q1.call_point_id | q }}
ORDER BY p.param_id

SELECT p.name, p.value_expr, p.value_kind, p.value_literals, p.added_by FROM param p JOIN event e USING(event_id)
WHERE e.system_id = {{ q1.system_id | q }} AND e.event_name = {{ q1.event_name | q }} AND e.call_point_id = {{ q1.call_point_id | q }}
ORDER BY p.param_id
